GS_ADD([{"id":"a-nl-record","reg":"Europe","mk":"NL","mkt":"Netherlands","auth":"KSA","cat":"Enforcement","date":"2026-03-10","v":"official","t":"Dutch regulator fines illegal operator a record €24.8 million","d":"Novatech, behind Qbet.com and 55Bet.com, did not block Dutch players.","b":["The KSA fined Novatech, which runs Qbet.com and 55Bet.com, €24,846,000, its highest fine on an illegal operator so far. Fortaprime SRL was fined €1,795,000 the same day. Neither blocked Dutch players, and both accepted crypto and anonymous payments. The KSA said Novatech's fine would have passed €100 million without the legal cap of 10% of worldwide turnover."],"src":[["KSA, 10 Mar 2026","https://kansspelautoriteit.nl/twee-boetes-voor-illegaal-aanbod-waaronder-recordboete-van-24-miljoen","o"]],"archive":true,"es":{"mkt":"Países Bajos","auth":"KSA","t":"El regulador neerlandés impone una multa récord de 24,8 millones de euros a un operador ilegal","d":"Novatech, responsable de Qbet.com y 55Bet.com, no bloqueaba a los jugadores neerlandeses.","b":["La KSA multó con 24.846.000 euros a Novatech, que gestiona Qbet.com y 55Bet.com, la mayor multa impuesta hasta ahora a un operador ilegal. Ese mismo día multó a Fortaprime SRL con 1.795.000 euros. Ninguna de las dos bloqueaba a los jugadores neerlandeses y ambas aceptaban criptomonedas y pagos anónimos. La KSA indicó que la multa de Novatech habría superado los 100 millones de euros de no existir el tope legal del 10% de la facturación mundial."]},"ru":{"mkt":"Нидерланды","auth":"KSA","t":"Нидерландский регулятор наложил на нелегального оператора рекордный штраф 24,8 млн евро","d":"Novatech, стоящая за Qbet.com и 55Bet.com, не блокировала игроков из Нидерландов.","b":["KSA оштрафовала Novatech, управляющую Qbet.com и 55Bet.com, на 24 846 000 евро. Это крупнейший на сегодня штраф регулятора в отношении нелегального оператора. В тот же день Fortaprime SRL была оштрафована на 1 795 000 евро. Ни одна из компаний не блокировала игроков из Нидерландов, обе принимали криптовалюту и анонимные платежи. По данным KSA, штраф Novatech превысил бы 100 млн евро, если бы не установленный законом предел в 10% мирового оборота."]}},{"id":"a-jm-gmis","reg":"Caribbean","mk":"JM","mkt":"Jamaica","auth":"BGLC","cat":"Licensing","date":"2026-03-28","v":"official","t":"Jamaica moves gaming licensing online, mandatory from 2027","d":"All applications and renewals must go through the GMIS portal from January 2027.","b":["The BGLC urged licensees to apply and renew through its GMIS online portal before the 31 March deadline. From January 2027 all licence applications and renewals must be made online. 2026 is an awareness year."],"src":[["Jamaica Information Service, 28 Mar 2026","https://jis.gov.jm/bglc-urges-licencees-to-use-gmis-online-portal-ahead-of-march-31-deadline/","o"]],"archive":true,"es":{"mkt":"Jamaica","auth":"BGLC","t":"Jamaica traslada las licencias de juego a internet, obligatorio desde 2027","d":"Todas las solicitudes y renovaciones deberán tramitarse en el portal GMIS a partir de enero de 2027.","b":["La BGLC instó a los titulares de licencia a solicitar y renovar sus licencias a través de su portal online GMIS antes del plazo del 31 de marzo. A partir de enero de 2027, todas las solicitudes y renovaciones de licencias deberán hacerse online. 2026 es un año de sensibilización."]},"ru":{"mkt":"Ямайка","auth":"BGLC","t":"Ямайка переводит лицензирование игорного бизнеса в онлайн, обязательно с 2027 года","d":"С января 2027 года все заявки и продления подаются только через портал GMIS.","b":["Регулятор BGLC призвал лицензиатов подавать заявки и продлевать лицензии через онлайн-портал GMIS до истечения срока 31 марта. С января 2027 года все заявки на лицензии и их продление принимаются только онлайн. 2026 год объявлен ознакомительным."]}},{"id":"a-mw-ads","reg":"Africa","mk":"MW","mkt":"Malawi","auth":"MAGLA","cat":"Advertising","date":"2026-03-17","v":"official","t":"Malawi limits gambling ads to 9pm to 6am","d":"The rule binds operators, not broadcasters. The regulator named child protection as the aim.","b":["At a meeting in Blantyre, Malawi's gaming regulator said Directive No. 1 of 2025 allows gambling ads only between 21:00 and 06:00. The directive binds operators rather than broadcasters, and the regulator chose it over a full ban. Broadcasters warned of lost ad revenue, and the regulator said it would review their feedback."],"src":[["MAGLA news","https://magla.org.mw/category/news/","o"],["AllAfrica","https://allafrica.com/stories/202603200212.html","p"]],"archive":true,"es":{"mkt":"Malaui","auth":"MAGLA","t":"Malaui limita los anuncios de juego a la franja de 21:00 a 06:00","d":"La norma obliga a los operadores, no a las emisoras. El regulador citó la protección de menores como objetivo.","b":["En una reunión en Blantyre, el regulador del juego de Malaui explicó que la Directiva n.º 1 de 2025 solo permite anuncios de juego entre las 21:00 y las 06:00. La directiva obliga a los operadores y no a las emisoras, y el regulador la prefirió a una prohibición total. Las emisoras advirtieron de la pérdida de ingresos publicitarios, y el regulador dijo que estudiará sus comentarios."]},"ru":{"mkt":"Малави","auth":"MAGLA","t":"Малави разрешила рекламу азартных игр только с 9 вечера до 6 утра","d":"Правило обязательно для операторов, а не для вещателей. Регулятор назвал целью защиту детей.","b":["На встрече в Блантайре игорный регулятор Малави заявил, что директива № 1 от 2025 года разрешает рекламу азартных игр только с 21:00 до 06:00. Директива обязательна для операторов, а не для вещателей. Регулятор предпочел ее полному запрету. Вещатели предупредили о потере рекламных доходов, и регулятор обещал рассмотреть их замечания."]}},{"id":"a-ph-mgf","reg":"Asia","mk":"PH","mkt":"Philippines","auth":"PAGCOR","cat":"Tax","date":"2026-03-30","v":"official","t":"PAGCOR defers minimum guaranteed fee for system administrators twice","d":"The fee now starts on 1 July 2026 after a second deferral approved on 21 May.","b":["A PAGCOR memo of 30 March 2026 said the board had deferred the minimum guaranteed fee for gaming system administrators by two months, to 1 June 2026, citing the economic crisis.","A second memo of 21 May said the board had deferred it again, to 30 June, to give operators time to recover from market contraction. The first tranche now runs from 1 July to 31 December 2026.","In that tranche, administrators with electronic casino games pay at least PHP 9 million a month, linked to a PHP 30 million monthly revenue threshold. Those without casino games pay PHP 3 million, linked to PHP 15 million. From 1 January 2027 the figures rise to PHP 10.5 million and PHP 4 million."],"src":[["PAGCOR memo, 30 March 2026","https://www.pagcor.ph/regulatory/pdf/announcements/Memorandum-on-Deferment-of-Period-for-the-Implementation-of-the-Imposition-of-Minimum-Guaranteed-Fee.pdf","o"],["PAGCOR memo, 21 May 2026","https://www.pagcor.ph/regulatory/pdf/announcements/Memorandum-on-Extension-of-the-Effectivity-of-the-Minimum-Guaranteed-Fee-for-Gaming-System-Administrators.pdf","o"],["PAGCOR, announcements","https://www.pagcor.ph/regulatory/announcements-ebld.php","o"]],"archive":true,"es":{"mkt":"Filipinas","auth":"PAGCOR","t":"PAGCOR aplaza dos veces la tasa mínima garantizada para los administradores de sistemas","d":"La tasa empieza ahora el 1 de julio de 2026, tras un segundo aplazamiento aprobado el 21 de mayo.","b":["Un memorando de PAGCOR de 30 de marzo de 2026 indicó que el consejo había aplazado dos meses la tasa mínima garantizada para los administradores de sistemas de juego, hasta el 1 de junio de 2026, por la crisis económica.","Un segundo memorando de 21 de mayo señaló que el consejo la había aplazado de nuevo, hasta el 30 de junio, para dar tiempo a los operadores a recuperarse de la contracción del mercado. El primer tramo va ahora del 1 de julio al 31 de diciembre de 2026.","En ese tramo, los administradores con juegos de casino electrónicos pagan al menos 9 millones de PHP al mes, vinculados a un umbral de ingresos mensuales de 30 millones de PHP. Los que no tienen juegos de casino pagan 3 millones de PHP, vinculados a 15 millones. Desde el 1 de enero de 2027 las cifras suben a 10,5 millones y 4 millones de PHP."]},"ru":{"mkt":"Филиппины","auth":"PAGCOR","t":"PAGCOR дважды отложила минимальный гарантированный сбор для системных администраторов","d":"После второй отсрочки, утвержденной 21 мая, сбор начнет действовать с 1 июля 2026 года.","b":["В меморандуме PAGCOR от 30 марта 2026 года говорилось, что совет директоров отложил минимальный гарантированный сбор для администраторов игровых систем на два месяца, до 1 июня 2026 года, сославшись на экономический кризис.","Во втором меморандуме от 21 мая сообщалось, что совет снова отложил сбор, до 30 июня, чтобы дать операторам время восстановиться после сжатия рынка. Первый транш теперь действует с 1 июля по 31 декабря 2026 года.","В этом транше администраторы с электронными играми казино платят не менее 9 млн филиппинских песо в месяц при пороге ежемесячной выручки 30 млн песо. Администраторы без игр казино платят 3 млн песо при пороге 15 млн песо. С 1 января 2027 года суммы вырастут до 10,5 млн песо и 4 млн песо."]}},{"id":"a-mo-ggr","reg":"Asia","mk":"MO","mkt":"Macau","auth":"DICJ","cat":"Market data","date":"2026-03-01","v":"official","t":"Macau gaming revenue up 3.2% after nine months of 2026","d":"Revenue reached MOP 187.1 billion by September, though growth has slowed since June.","b":["Macau's gaming regulator reports gross gaming revenue of MOP 43.26 billion for January and February 2026, up 13.9% on a year earlier. January alone rose 24.0% to MOP 22.63 billion.","Growth then slowed. March brought MOP 22.61 billion and May MOP 22.61 billion. June fell 12.1% to MOP 18.52 billion, and July, August and September were also below 2025 levels.","Revenue for the first nine months totalled MOP 187.12 billion, up 3.2% on the same period of 2025."],"src":[["DICJ, monthly gross revenue 2026","https://www.dicj.gov.mo/web/en/information/DadosEstat_mensal/2026/index.html","o"],["SiGMA","https://sigma.world/news/macau-casinos-clear-annual-benchmark-in-first-two-months/","p"]],"archive":true,"es":{"mkt":"Macao","auth":"DICJ","t":"Los ingresos del juego en Macao suben un 3,2% en los nueve primeros meses de 2026","d":"Los ingresos alcanzaron 187.100 millones de MOP hasta septiembre, aunque el crecimiento se ha frenado desde junio.","b":["El regulador del juego de Macao registra unos ingresos brutos del juego (GGR) de 43.260 millones de MOP en enero y febrero de 2026, un 13,9% más que un año antes. Solo enero subió un 24,0%, hasta 22.630 millones de MOP.","Después el crecimiento se frenó. Marzo dejó 22.610 millones de MOP y mayo, 22.610 millones. Junio cayó un 12,1%, hasta 18.520 millones de MOP, y julio, agosto y septiembre también quedaron por debajo de los niveles de 2025.","Los ingresos de los nueve primeros meses sumaron 187.120 millones de MOP, un 3,2% más que en el mismo periodo de 2025."]},"ru":{"mkt":"Макао","auth":"DICJ","t":"Игорный доход Макао за девять месяцев 2026 года вырос на 3,2%","d":"К сентябрю доход достиг 187,1 млрд патак, хотя с июня рост замедлился.","b":["По данным игорного регулятора Макао, валовой игорный доход (GGR) за январь и февраль 2026 года составил 43,26 млрд патак, на 13,9% больше, чем годом ранее. Только в январе доход вырос на 24,0% до 22,63 млрд патак.","Затем рост замедлился. Март принес 22,61 млрд патак, май также 22,61 млрд патак. В июне доход снизился на 12,1% до 18,52 млрд патак, а в июле, августе и сентябре также был ниже уровня 2025 года.","Доход за первые девять месяцев составил 187,12 млрд патак, на 3,2% больше, чем за тот же период 2025 года."]}},{"id":"a-fi-apps","reg":"Europe","mk":"FI","mkt":"Finland","auth":"National Police Board","cat":"Licensing","date":"2026-03-01","v":"official","t":"Finland opens licence applications for its competitive market","d":"Licensing rules took effect on 1 March 2026. The rest of the Gambling Act applies from 1 July 2027.","b":["Finland's Gambling Act (10/2026) was adopted on 16 January 2026. Its licensing chapter and several related sections took effect early, on 1 March 2026, so operators can apply for gambling licences and the exclusive licence before the market opens.","The Act as a whole comes into force on 1 July 2027. The National Police Board acts as the licensing authority until 30 June 2027, after which its tasks move to a new licensing and supervisory agency. Rules on game software licences apply from 1 July 2027."],"src":[["Finlex, Gambling Act 10/2026","https://www.finlex.fi/fi/lainsaadanto/2026/10","o"],["Police of Finland, licences under the Gambling Act","https://poliisi.fi/en/licences-under-the-gambling-act","o"],["Yogonet","https://www.yogonet.com/international/news/2026/06/11/123584-finland-draws-nearly-50-gambling-license-applications-more-than-a-year-before-market-launch","p"]],"archive":true,"es":{"mkt":"Finlandia","auth":"Junta Nacional de Policía","t":"Finlandia abre la solicitud de licencias para su mercado competitivo","d":"Las normas de licencias entraron en vigor el 1 de marzo de 2026. El resto de la Ley de Juego se aplica desde el 1 de julio de 2027.","b":["La Ley de Juego de Finlandia (10/2026) se aprobó el 16 de enero de 2026. Su capítulo de licencias y varios artículos relacionados entraron en vigor de forma anticipada, el 1 de marzo de 2026, para que los operadores puedan solicitar licencias de juego y la licencia exclusiva antes de la apertura del mercado.","La ley en su conjunto entra en vigor el 1 de julio de 2027. La Junta Nacional de Policía actúa como autoridad de licencias hasta el 30 de junio de 2027. Después, sus funciones pasan a una nueva agencia de licencias y supervisión. Las normas sobre licencias de software de juego se aplican desde el 1 de julio de 2027."]},"ru":{"mkt":"Финляндия","auth":"National Police Board","t":"Финляндия открыла прием заявок на лицензии для конкурентного рынка","d":"Правила лицензирования вступили в силу 1 марта 2026 года. Остальные положения Закона об азартных играх применяются с 1 июля 2027 года.","b":["Закон Финляндии об азартных играх (10/2026) был принят 16 января 2026 года. Его глава о лицензировании и ряд связанных статей вступили в силу досрочно, 1 марта 2026 года, чтобы операторы могли подать заявки на лицензии на азартные игры и на исключительную лицензию до открытия рынка.","Закон в целом вступает в силу 1 июля 2027 года. До 30 июня 2027 года функции лицензирующего органа выполняет Национальное полицейское управление, после чего его задачи перейдут к новому агентству по лицензированию и надзору. Правила о лицензиях на игровое программное обеспечение применяются с 1 июля 2027 года."]}},{"id":"a-pr-sb960","reg":"Caribbean","mk":"PR","mkt":"Puerto Rico","auth":"Senate","cat":"Legislation","date":"2026-03-26","v":"official","t":"Puerto Rico Senate bill would allow poker rooms and esports betting","d":"Bill 960 proposes 15% on poker rooms and 12% on esports betting. The legislature's budget office sees almost no revenue gain.","b":["Senate Bill 960 would amend the Gaming Commission law (Law 81-2019) to widen legal gambling. It would allow standalone poker rooms with at least 10 tables, taxed at 15% of gross revenue, and betting on certified esports events, taxed at 12% of net winnings.","It would also allow interactive electronic lotteries, with 20% of revenue going to social programmes, and more online sports betting platforms, including international operators with local licences. Licensees would put 5% of revenue into problem gambling prevention and education.","In a March 2026 report, the Legislative Assembly's budget office said the bill would bring close to no extra revenue, because new games would mostly replace spending on existing ones."],"src":[["OPAL, fiscal report 2026-402 on P. del S. 960","https://www.opal.pr.gov/informes/informe-2026-402-ps-960","o"],["Yogonet, 26 Mar 2026","https://www.yogonet.com/latinoamerica/noticias/2026/03/26/108220-proponen-ampliar-la-oferta-de-juegos-de-azar-en-puerto-rico-y-generar-mas-ingresos-al-estado","p"]],"archive":true,"es":{"mkt":"Puerto Rico","auth":"Senado","t":"Un proyecto del Senado de Puerto Rico permitiría salas de póquer y apuestas en esports","d":"El Proyecto 960 propone un 15% sobre las salas de póquer y un 12% sobre las apuestas en esports. La oficina de presupuesto de la Asamblea Legislativa prevé un aumento de recaudación casi nulo.","b":["El Proyecto del Senado 960 modificaría la ley de la Comisión de Juegos (Ley 81-2019) para ampliar el juego legal. Permitiría salas de póquer independientes con al menos 10 mesas, gravadas con un 15% de los ingresos brutos, y apuestas en eventos certificados de esports, gravadas con un 12% de las ganancias netas.","También permitiría loterías electrónicas interactivas, con un 20% de los ingresos destinado a programas sociales, y más plataformas de apuestas deportivas online, incluidos operadores internacionales con licencia local. Los titulares de licencia destinarían un 5% de los ingresos a la prevención y la educación sobre el juego problemático.","En un informe de marzo de 2026, la oficina de presupuesto de la Asamblea Legislativa indicó que el proyecto apenas aportaría recaudación adicional, porque los nuevos juegos sustituirían sobre todo el gasto en los existentes."]},"ru":{"mkt":"Пуэрто-Рико","auth":"Сенат","t":"Законопроект Сената Пуэрто-Рико разрешает покерные залы и ставки на киберспорт","d":"Законопроект 960 предлагает налог 15% для покерных залов и 12% для ставок на киберспорт. Бюджетное управление законодательного органа почти не ожидает роста доходов.","b":["Законопроект Сената 960 вносит изменения в закон об Игорной комиссии (Закон 81-2019) и расширяет круг легальных азартных игр. Он разрешает отдельные покерные залы не менее чем с 10 столами с налогом 15% от валовой выручки, а также ставки на сертифицированные киберспортивные события с налогом 12% от чистого выигрыша.","Законопроект также разрешает интерактивные электронные лотереи, 20% выручки от которых будут направляться на социальные программы, и увеличивает число платформ онлайн-ставок на спорт, включая международных операторов с местными лицензиями. Лицензиаты будут направлять 5% выручки на профилактику игровой зависимости и просвещение.","В докладе за март 2026 года бюджетное управление Законодательного собрания указало, что законопроект почти не принесет дополнительных доходов, поскольку новые игры в основном заменят расходы на существующие."]}},{"id":"a-ua-patriot","reg":"Europe","mk":"UA","mkt":"Ukraine","auth":"PlayCity","cat":"Licensing","date":"2026-03-25","v":"official","t":"Ukraine strips Patriot of lottery operator status; court suspends the decision","d":"PlayCity cited the ultimate beneficial owner's failure to meet legal requirements. An administrative court has since suspended the decision.","b":["PlayCity decision No. 84-R of 25 March 2026 removed PrJSC Patriot's status as a state lottery operator by ending the lottery licence granted in February 2026.","The regulator said the ultimate beneficial owner did not meet the requirements of the state lotteries law and the licence conditions, and that the operator also failed other requirements of that law. It referred to letters from the State Bureau of Investigation.","A note added to the decision says the Dnipropetrovsk District Administrative Court suspended it on 5 June 2026, as an interim measure, until the court case is finally decided."],"src":[["PlayCity, decision 84-R","https://playcity.gov.ua/npas/rishennia-ahentstva-pleisiti-vid-25032026r-84-r-pro-pozbavlennia-statusu-operatora-derzhavnykh-loterei-prat-patriot-shliakhom-prypynennia-dii-litsenzii-na-provadzhennia-hospodarskoi-diialnost","o"],["UA.News","https://ua.news/en/all-news/playcity-anuliuvalo-litsenziiu-lotereinogo-operatora-patriot","p"]],"archive":true,"es":{"mkt":"Ucrania","auth":"PlayCity","t":"Ucrania retira a Patriot la condición de operador de lotería y un tribunal suspende la decisión","d":"PlayCity alegó que el titular real no cumplía los requisitos legales. Un tribunal administrativo ha suspendido después la decisión.","b":["La decisión n.º 84-R de PlayCity, de 25 de marzo de 2026, retiró a PrJSC Patriot la condición de operador de la lotería estatal al poner fin a la licencia de lotería concedida en febrero de 2026.","El regulador afirmó que el titular real no cumplía los requisitos de la ley de loterías estatales ni las condiciones de la licencia, y que el operador también incumplía otros requisitos de esa ley. Hizo referencia a cartas de la Oficina Estatal de Investigación.","Una nota añadida a la decisión indica que el Tribunal Administrativo de Distrito de Dnipropetrovsk la suspendió el 5 de junio de 2026, como medida cautelar, hasta que el caso se resuelva de forma definitiva."]},"ru":{"mkt":"Украина","auth":"PlayCity","t":"Украина лишила Patriot статуса оператора лотерей, суд приостановил решение","d":"PlayCity сослался на несоответствие конечного бенефициарного владельца требованиям закона. Административный суд впоследствии приостановил решение.","b":["Решением PlayCity № 84-R от 25 марта 2026 года PrJSC Patriot лишено статуса оператора государственных лотерей путем прекращения действия лотерейной лицензии, выданной в феврале 2026 года.","Регулятор указал, что конечный бенефициарный владелец не соответствовал требованиям закона о государственных лотереях и лицензионным условиям, а оператор также нарушил другие требования этого закона. Регулятор сослался на письма Государственного бюро расследований.","Согласно примечанию к решению, Днепропетровский окружной административный суд 5 июня 2026 года приостановил его действие в качестве обеспечительной меры до окончательного разрешения дела."]}}]);
